#!/usr/bin/env bash
# AI DISCLAIMER: All of the text in this file was generated by AI.
# hdd_stage1c.sh (kit v12): G016 stage 1c on the HDD, a 7,000-block sync per run: candidate 3h against .6's path (the
# timing stages), and a traced diagnosis of 3e's and 3f's reads. For the HDD VM.
# ARMS x ROUNDS, the arm order rotated left by one each round (ARMS "F N", ROUNDS 2: F N, N F).
# Arms and binaries (one switch, MONERODATO_NO_DROP_FREED, as in kit v9):
#   F   BIN_3H (3h: 3f's LMDB drop plus a prefetch of the pruned runs' first pages in monerod's pruning; LMDB prints 3f's lines,
#       monerod prints G016 3h: lines; BIN_3G and BIN_3F are accepted as fallback names), drop on: the driver removes
#       MONERODATO_NO_DROP_FREED, MONERODATO_G016_PREFETCH_BLOCKS and MONERODATO_G016_PREFETCH_MAX from monerod's environment
#   N   BIN_3H, drop off (look-ahead 0): MONERODATO_NO_DROP_FREED=1; LMDB then runs .6's code path (no cache advice at all)
#   W   BIN_3EWL (kit v9's 3e plus a page-event log), drop on, run through hdd_trace.sh (block-I/O trace, sampler)
#   V   BIN_3FWL (3f plus the page-event log), drop on, run through hdd_trace.sh
# Kit v12 runs F and N only; W and V stay supported here, unchanged.
# For W and V the driver sets MONERODATO_G016_WLOG=<stage dir>/trace-<label>/g016_wlog.txt: LMDB appends one line per
# page it writes (W), per page a commit frees (F), per range 3e/3f drops (D) and per commit (C).
# Each run is one hdd_run.sh call (v6, unchanged) from SNAP_MDB, cold, to TARGET_TOP 3,113,400, WINDOW_BLOCKS 1000, no
# WARM_DBS and no WARM_TOOL, ending with hdd_run.sh's hash check of the top block against the peer's.
# After each run the driver reads monerod's stderr (stdout.txt): with the drop on, LMDB prints "LMDB G016 3f: ..." (3h's, as 3f's), "LMDB G016 3g: ..."
# (3g) or "LMDB G016 3e: ..." (3e) every 100 commits; with it off, nothing. It appends
#   DROP label=<label> arm=<arm> kind=<3e|3f|3g|na> lines=<n> commits=<c> freed=<f> now=<d> deferred=<e> forced=<x>
#        skipped=<s> skipov=<o> fdkept=<k> held=<h> kept=<k> cachestat=<s>
# (the last line's numbers, else na; "now" is 3e's "dropped at once" or 3f's "dropped once no reader saw them", held
# is 3f's "held for readers", kept is 3g's "overflow first pages kept"). In every arm monerod (3h) prints "G016 3h: height ..." every 50 prune
# calls; from the last such line the driver appends
#   PREFETCH label=<label> arm=<arm> lines=<n> height=<h> calls=<c> prune_s=<x> pass_s=<y> passes=<p> lookahead=<L> max=<m>
#        advised=<records advised> deleted=<records deleted> deleted_ov=<with an overflow run> resident=<resident at delete>
# (every value na when there is no such line). For W and V it also appends hdd_trace.sh's TRACE line, to results.txt.
# Each run's sync is capped at RUN_TIMEOUT_S (default 9000 s). A timeout or an OOM-kill is a result (hdd_run.sh exits 0)
# and the stage goes on; it stops only at an abort (hdd_run.sh or hdd_trace.sh exit != 0): STAGE1C_ABORT.
# MEM_MAX, if set, is passed to every run (default: unset, no scope).
# Collects RESULT, IOSTAT, WINDOW, DROP, PREFETCH and TRACE lines into $OUT_BASE/stage1c-<start time>/results.txt; prints
# STAGE1C_DONE.
#
# usage: hdd_stage1c.sh
# environment: as hdd_run.sh (SNAP_MDB, DATA_DIR, PEER, OUT_BASE), plus
#   BIN_3H (arms F, N; BIN_3G and BIN_3F are fallback names); BIN_3EWL (arm W); BIN_3FWL (arm V); ARMS (default "F N"); ROUNDS (default 2); RUN_TIMEOUT_S;
#   TARGET_TOP (default 3113400); MEM_MAX;
#   RUN    path of hdd_run.sh (default: hddkit12-hdd_run.sh, else hdd_run.sh, next to this script)
#   TRACE  path of hdd_trace.sh (default: hddkit12-hdd_trace.sh, else hdd_trace.sh, next to this script)
set -u
: "${SNAP_MDB:?}" "${DATA_DIR:?}" "${PEER:?}"
export SNAP_MDB DATA_DIR PEER
export OUT_BASE=${OUT_BASE:-$HOME/hddruns}
here=$(dirname "$(realpath "$0")")
if [ -z "${RUN:-}" ]; then
  RUN=$here/hddkit12-hdd_run.sh; [ -f "$RUN" ] || RUN=$here/hdd_run.sh
fi
if [ -z "${TRACE:-}" ]; then
  TRACE=$here/hddkit12-hdd_trace.sh; [ -f "$TRACE" ] || TRACE=$here/hdd_trace.sh
fi
[ -f "$RUN" ] || { echo "hdd_run.sh not found (set RUN)"; exit 2; }
export RUN
ARMS=${ARMS:-F N}; ROUNDS=${ROUNDS:-2}; RUN_TIMEOUT_S=${RUN_TIMEOUT_S:-9000}; TARGET_TOP=${TARGET_TOP:-3113400}
BIN_3F=${BIN_3H:-${BIN_3G:-${BIN_3F:-}}}
need() { echo "$*"; exit 2; }
# every prerequisite is checked before the first run
bin_of() { case $1 in F|N) echo "${BIN_3F:-}";; W) echo "${BIN_3EWL:-}";; V) echo "${BIN_3FWL:-}";; esac; }
for a in $ARMS; do
  case $a in
    F|N) [ -x "${BIN_3F:-}" ] || need "BIN_3H/BIN_3G/BIN_3F ${BIN_3F:-(unset)} is not executable (arm $a)" ;;
    W) [ -x "${BIN_3EWL:-}" ] || need "BIN_3EWL ${BIN_3EWL:-(unset)} is not executable (arm W)" ;;
    V) [ -x "${BIN_3FWL:-}" ] || need "BIN_3FWL ${BIN_3FWL:-(unset)} is not executable (arm V)" ;;
    *) need "unknown arm $a" ;;
  esac
  case $a in W|V) [ -f "$TRACE" ] || need "hdd_trace.sh not found (set TRACE) for arm $a";; esac
done
[ -f "$SNAP_MDB" ] || need "SNAP_MDB $SNAP_MDB is not a file"
sudo -n true 2> /dev/null || need "sudo asks for a password; the runs need it for the cache drop (and W, V for bpftrace)"
ST=$OUT_BASE/stage1c-$(date -u +%Y%m%dT%H%M%SZ); mkdir -p "$ST"
lg() { echo "$*" | tee -a "$ST/log.txt"; }
lg "stage1c start $(date -u +%FT%TZ); rounds $ROUNDS; arms $ARMS; target top $TARGET_TOP; per-run timeout $RUN_TIMEOUT_S s; MEM_MAX ${MEM_MAX:-none}"
lg "run script $RUN ($(sha256sum "$RUN" | cut -c1-16)); this script $(sha256sum "$0" | cut -c1-16); trace script $TRACE ($(sha256sum "$TRACE" 2> /dev/null | cut -c1-16))"
for v in BIN_3H BIN_3G BIN_3F BIN_3EWL BIN_3FWL; do
  b=${!v:-}; [ -n "$b" ] && [ -x "$b" ] && lg "$v $b ($(sha256sum "$b" | cut -c1-16)) $("$b" --version 2> /dev/null | tail -1)"
done
# the snapshot is 11+ GB on the HDD: log size and mtime, not a hash (hashing it takes minutes of disk time)
lg "SNAP_MDB $SNAP_MDB ($(stat -c '%s bytes, mtime %y' "$SNAP_MDB"))"
lg "VM: nproc $(nproc); $(awk '/^(MemTotal|MemAvailable|SwapTotal)/ {printf "%s %s kB; ", $1, $2}' /proc/meminfo)kernel $(uname -r)"
read -ra AA <<< "$ARMS"; n=${#AA[@]}
for r in $(seq 1 "$ROUNDS"); do
  for i in $(seq 0 $((n - 1))); do
    a=${AA[$(( (i + r - 1) % n ))]}; o=$ST/r$r-$a.out; B=$(bin_of "$a"); TD=$ST/trace-r$r-$a
    lg "run round $r arm $a $(date -u +%FT%TZ)"
    case $a in
      F) env -u MONERODATO_NO_DROP_FREED -u MONERODATO_G016_PREFETCH_BLOCKS -u MONERODATO_G016_PREFETCH_MAX TIMEOUT_S="$RUN_TIMEOUT_S" TARGET_TOP="$TARGET_TOP" WINDOW_BLOCKS=1000 bash "$RUN" "r$r-F" "$B" ;;
      N) env -u MONERODATO_G016_PREFETCH_BLOCKS -u MONERODATO_G016_PREFETCH_MAX MONERODATO_NO_DROP_FREED=1 TIMEOUT_S="$RUN_TIMEOUT_S" TARGET_TOP="$TARGET_TOP" WINDOW_BLOCKS=1000 bash "$RUN" "r$r-N" "$B" ;;
      W|V) env -u MONERODATO_NO_DROP_FREED -u MONERODATO_G016_PREFETCH_BLOCKS -u MONERODATO_G016_PREFETCH_MAX MONERODATO_G016_WLOG="$TD/g016_wlog.txt" TIMEOUT_S="$RUN_TIMEOUT_S" TARGET_TOP="$TARGET_TOP" WINDOW_BLOCKS=1000 \
             bash "$TRACE" "$TD" "r$r-$a" "$B" ;;
    esac > "$o" 2>&1; rc=$?
    d=$(grep -oE 'HDD_RUN_DONE .*' "$o" | cut -d' ' -f2)
    [ $rc -eq 0 ] && [ -n "$d" ] || { tail -5 "$o" | tee -a "$ST/log.txt"; lg "STAGE1C_ABORT round $r arm $a rc=$rc"; exit 1; }
    grep -hE '^(RESULT|IOSTAT|WINDOW) ' "$d/summary.txt" >> "$ST/results.txt"
    dl=$(grep -cE 'LMDB G016 3[efg]: ' "$d/stdout.txt" 2> /dev/null); dl=${dl:-0}
    last=$(grep -E 'LMDB G016 3[efg]: ' "$d/stdout.txt" 2> /dev/null | tail -1)
    val() { echo "$last" | grep -oE "$1" | grep -oE '[0-9]+' | head -1; }
    if [ -n "$last" ]; then
      kd=$(echo "$last" | grep -oE 'LMDB G016 3[efg]' | grep -oE '3[efg]$')
      c=$(val '[0-9]+ commits'); f=$(val 'freed [0-9]+'); nw=$(val '[0-9]+ dropped (at once|once no reader saw them)'); df=$(val '[0-9]+ deferred'); fo=$(val 'forced [0-9]+')
      sk=$(val 'skipped reused [0-9]+'); so=$(val 'skipped reused overflow [0-9]+'); fk=$(val 'free-list overflow kept [0-9]+'); hd=$(val 'held for readers [0-9]+'); kp=$(val 'overflow first pages kept [0-9]+')
      cs=$(echo "$last" | grep -oE 'cachestat [a-z]+' | cut -d' ' -f2)
    else
      kd=na; c=na; f=na; nw=na; df=na; fo=na; sk=na; so=na; fk=na; hd=na; kp=na; cs=na
    fi
    echo "DROP label=r$r-$a arm=$a kind=${kd:-na} lines=$dl commits=${c:-na} freed=${f:-na} now=${nw:-na} deferred=${df:-na} forced=${fo:-na} skipped=${sk:-na} skipov=${so:-na} fdkept=${fk:-na} held=${hd:-na} kept=${kp:-na} cachestat=${cs:-na}" >> "$ST/results.txt"
    pn=$(grep -c 'G016 3h: height ' "$d/stdout.txt" 2> /dev/null); pn=${pn:-0}
    pl=$(grep 'G016 3h: height ' "$d/stdout.txt" 2> /dev/null | tail -1)
    pv() { [ -n "$pl" ] && echo "$pl" | sed -nE "s/.*[^0-9.]$1.*/\1/p" | head -1; }
    echo "PREFETCH label=r$r-$a arm=$a lines=$pn height=$(pv 'height ([0-9]+);' | grep . || echo na) calls=$(pv '([0-9]+) prune calls' | grep . || echo na) prune_s=$(pv '([0-9.]+) s in pruning' | grep . || echo na) pass_s=$(pv '([0-9.]+) s in [0-9]+ prefetch passes' | grep . || echo na) passes=$(pv 's in ([0-9]+) prefetch passes' | grep . || echo na) lookahead=$(pv 'look-ahead ([0-9]+) blocks' | grep . || echo na) max=$(pv 'max ([0-9]+) records' | grep . || echo na) advised=$(pv 'advised ([0-9]+) records' | grep . || echo na) deleted=$(pv 'deleted ([0-9]+) records' | grep . || echo na) deleted_ov=$(pv '([0-9]+) with an overflow run' | grep . || echo na) resident=$(pv '([0-9]+) of those resident at delete' | grep . || echo na)" >> "$ST/results.txt"
    case $a in W|V) grep -hE '^TRACE ' "$o" | tail -1 >> "$ST/results.txt";; esac
    echo "$d" >> "$ST/rundirs.txt"
    lg "done round $r arm $a: $(grep -h '^RESULT' "$d/summary.txt" | grep -oE ' (top|launch_to_top_s|steady_blocks_per_s|disk_read_MB|outcome)=[^ ]*' | paste -sd' ') drop lines $dl; 3h lines $pn"
  done
done
lg "STAGE1C_DONE $(date -u +%FT%TZ) $ST"
